function Files=w2e_export(outdir,PairResults,Samples,Summary,Report,O)
%W2E_EXPORT Auditable ledgers. No performance pair is silently dropped.
N=numel(PairResults);RunRows=cell(2*N,1);PairRows=cell(N,1);ErrRows=cell(0,1);RoleLong=cell(36*N,1);MarginLong=cell(36*N,1);q=0;qm=0;
rowNames=w2b_row_names();stateNames={'hVmin';'hVmax';'hGammaMin';'hGammaMax';'psiVmin';'psiVmax';'psiGammaMin';'psiGammaMax';'rateV';'rateGamma';'rateChi';'aGamma';'bank';'Nminus';'Nplus';'Tlower';'Tupper';'backup'};
for k=1:N
 P=PairResults{k};runs={P.Proposed,P.MatchedQP};PairRows{k}=P.Pair;
 for im=1:2,E=runs{im};RunRows{2*(k-1)+im}=w2e_run_scalar_row(E);if ~E.Completed||~E.CorePass,ErrRows{end+1}=struct('Index',E.Index,'Method',E.Method,'Completed',E.Completed,'CorePass',E.CorePass,'FailureClass',E.FailureClass,'ErrorId',E.ErrorId,'ErrorMessage',E.ErrorMessage,'HardFeasible',E.HardFeasible,'ReferenceNormalizedPass',E.ReferenceNormalizedPass,'BackupSetPass',E.BackupSetPass,'QPKKTGatePass',E.QPKKTGatePass);end %#ok<AGROW>
  for j=1:18,q=q+1;RoleLong{q}=struct('Index',E.Index,'Method',E.Method,'RowIndex',j,'Row',rowNames{j},'SelectionRoleCount',E.RoleCount(j),'BindingCount',E.BindingCount(j),'MinAppliedPhi',E.AffineMin(j),'MinNominalPhi',E.NominalAffineMin(j));qm=qm+1;MarginLong{qm}=struct('Index',E.Index,'Method',E.Method,'Margin',stateNames{j},'MinValue',E.StateMarginMin(j));end
 end
end
writetable(struct2table([RunRows{:}]),fullfile(outdir,'W2E_method_results.csv'));writetable(struct2table([PairRows{:}]),fullfile(outdir,'W2E_pair_results.csv'));writetable(struct2table([RoleLong{:}]),fullfile(outdir,'W2E_constraint_role_ledger.csv'));writetable(struct2table([MarginLong{:}]),fullfile(outdir,'W2E_state_margin_ledger.csv'));if ~isempty(ErrRows),writetable(struct2table([ErrRows{:}]),fullfile(outdir,'W2E_error_ledger.csv'));else,fid=fopen(fullfile(outdir,'W2E_error_ledger.csv'),'w');fprintf(fid,'No non-complete or core-gate-failed runs.\n');fclose(fid);end
writetable(struct2table([Summary.PairedMetricRows{:}]),fullfile(outdir,'W2E_paired_metric_summary.csv'));writetable(struct2table([Summary.RoleRows{:}]),fullfile(outdir,'W2E_constraint_role_summary.csv'));
% Compact sample descriptors; complete vectors remain in Report.Samples and the immutable sample-source MAT.
SR=cell(N,1);for k=1:N,s=Samples(k);SR{k}=struct('Index',s.index,'MassScale',s.massScale,'AeroMaxDeviationPct',s.aeroMaxDeviationPct,'WindPeakBound',s.windPeakBound,'NoiseScale',s.noiseScale,'ThrustTauScale',s.thrustTauScale,'InitAttitudeRotNorm_deg',rad2deg(norm(s.initAttitudeRotvec)));end;writetable(struct2table([SR{:}]),fullfile(outdir,'W2E_sample_summary.csv'));
summaryFile=fullfile(outdir,'W2E_SUMMARY.txt');writeSummary(summaryFile,Summary,O);save(fullfile(outdir,'W2E_Report.mat'),'Report','-v7.3');Files=struct('methodResults',fullfile(outdir,'W2E_method_results.csv'),'pairResults',fullfile(outdir,'W2E_pair_results.csv'),'pairedMetricSummary',fullfile(outdir,'W2E_paired_metric_summary.csv'),'roleSummary',fullfile(outdir,'W2E_constraint_role_summary.csv'),'errorLedger',fullfile(outdir,'W2E_error_ledger.csv'),'summary',summaryFile,'mat',fullfile(outdir,'W2E_Report.mat'));
end
function writeSummary(file,S,O)
fid=fopen(file,'w');if fid<0,error('W2E:Export','Cannot create %s',file);end;c=onCleanup(@()fclose(fid));fprintf(fid,'Paper 1 -> Aerospace W2-E PAIRED MONTE CARLO SUMMARY\n');fprintf(fid,'===================================================\n\n');fprintf(fid,'Protocol: %s\nN paired uncertainty records: %d\nrhoB: %.2f\n\n',O.ProtocolID,S.N,O.RhoB);printMethod(fid,S.Proposed);printMethod(fid,S.MatchedQP);fprintf(fid,'PAIR OUTCOMES\n-------------\nBoth completed: %d/%d\nBoth hard-feasible: %d/%d\nBoth CorePass: %d/%d\nBoth certified-domain diagnostic: %d/%d\nProposed-only CorePass: %d\nQP-only CorePass: %d\nNeither CorePass: %d\nExecution-discordant pairs: %d\n\n',S.Pair.NBothCompleted,S.N,S.Pair.NBothHardFeasible,S.N,S.Pair.NBothCorePass,S.N,S.Pair.NBothCertifiedDomain,S.N,S.Pair.NProposedOnlyCorePass,S.Pair.NQPOnlyCorePass,S.Pair.NNeitherCorePass,S.Pair.NExecutionDiscordant);fprintf(fid,'PAIRED CONTINUOUS METRICS\n-------------------------\nPopulation: %s\nDelta convention: MatchedQP - Proposed. No numeric failure penalty is imputed.\n',S.Pair.PerformancePopulation);for k=1:numel(S.PairedMetricRows),r=S.PairedMetricRows{k};fprintf(fid,'%-28s N=%d mean=% .8g median=% .8g q05=% .8g q95=% .8g fracQPlo=%.4f fracPlo=%.4f tie=%.4f\n',r.Metric,r.N,r.Mean_QPminusProposed,r.Median,r.Q05,r.Q95,r.FracQPLower,r.FracProposedLower,r.FracTie);end;fprintf(fid,'\nINTERPRETATION LOCK\n-------------------\n1. The 500 uncertainty records are the complete saved Rev.4.1.1 Samples, not a new random draw.\n2. Each record is used by both methods. All 500 pair outcomes remain in the outcome ledger.\n3. Continuous paired differences are reported only for BothCorePass pairs; failed pairs are not assigned artificial penalties.\n4. Frequencies are empirical outcomes under the stated study-defined ensemble, not real-world reliability probabilities.\n5. This campaign compares two reference-selection mechanisms under the same rhoB=0.10 feasible-set construction and downstream loop; it is not a general controller ranking.\n6. Parallel wall time and worker run times are not publication algorithm-runtime benchmarks.\n');
end
function printMethod(fid,M)
fprintf(fid,'%s\n',upper(M.Method));fprintf(fid,'  completed / hard / core / certified = %d / %d / %d / %d of %d\n',M.NCompleted,M.NHardFeasible,M.NCorePass,M.NCertifiedDomain,M.N);fprintf(fid,'  domain exits / numerical failures = %d / %d\n',M.NDomainExit,M.NNumericalFailure);fprintf(fid,'  completed but CorePass-failed = %d\n',M.NCompletedCoreGateFail);fprintf(fid,'  raw-chart / backup / reference-inversion / feedback-inversion / physical-geometry / QP-solver = %d / %d / %d / %d / %d / %d\n',M.NRawChartExit,M.NBackupExit,M.NInversionExit,M.NFeedbackInversionExit,M.NPhysicalGeometryExit,M.NQPSolverFailure);fprintf(fid,'  completed normalized-reference / backup-set / KKT gate fails = %d / %d / %d\n',M.NReferenceNormalizedFail,M.NBackupSetFail,M.NQPKKTGateFail);fprintf(fid,'  CorePass position RMS q50/q95/q99 = %.6g %.6g %.6g m\n',M.PosRMSFullQ);fprintf(fid,'  CorePass late peak q50/q95/q99 = %.6g %.6g %.6g m\n\n',M.PosPeakLateQ);
end
